from __future__ import annotations
from typing import Sequence

def path_five_count(a: Sequence[Sequence[float]]) -> float:
    """Return hom(P5,A) in O(n^2) time for a dense symmetric matrix."""
    n=len(a)
    if any(len(row)!=n for row in a): raise ValueError("square matrix required")
    d=[sum(row) for row in a]
    u=[sum(a[i][j]*d[j] for j in range(n)) for i in range(n)]
    return sum(value*value for value in u)

from __future__ import annotations
from typing import Iterable

def sparse_path_statistics(n: int, edges: Iterable[tuple[int,int,float]]) -> tuple[float,float]:
    """Evaluate S and P from symmetric directed sparse entries in O(m+n)."""
    rows: list[list[tuple[int,float]]]=[[] for _ in range(n)]
    for i,j,w in edges:
        rows[i].append((j,w))
    d=[sum(w for _,w in row) for row in rows]
    u=[sum(w*d[j] for j,w in row) for row in rows]
    return sum(d), sum(x*x for x in u)

