 n=5; a=[[0.0]*n for _ in range(n)]
 for i in range(n):
  for j in range(i,n): a[i][j]=a[j][i]=rng.uniform(-1,1)
 d=[sum(r) for r in a]; u=[sum(a[i][j]*d[j] for j in range(n)) for i in range(n)]
 s=sum(d); p=sum(x*x for x in u); xs.append(s**4); ys.append(n**3*p)
limit=max(xs+ys); plt.scatter(xs,ys,s=10,alpha=.55); plt.plot([0,limit],[0,limit],'k--')
plt.xlabel(r'$S^4$'); plt.ylabel(r'$n^3P$'); plt.title('Every sample lies above the sharp boundary')
